#include <bits/stdc++.h>
using namespace std;

int main() {
    long long a, c;
    cin >> a >> c;

    vector<int> av, cv;

    do {
        av.push_back(a % 3);
        a /= 3;
    } while (a > 0);

    do {
        cv.push_back(c % 3);
        c /= 3;
    } while (c > 0);

    size_t n = max(av.size(), cv.size());
    av.resize(n, 0);
    cv.resize(n, 0);

    long long b = 0, power = 1;
    for (size_t i = 0; i < n; ++i) {
        int digit = (cv[i] - av[i] + 3) % 3;
        b += digit * power;
        power *= 3;
    }

    cout << b << '\n';
    return 0;
}

