#include <bits/stdc++.h>
using namespace std;

int main() {
    long long a, c;
    cin >> a >> c;

    long long b = 0, place = 1;

    while (a > 0 || c > 0) {
        int digitA = a % 3;
        int digitC = c % 3;
        int digitB = (digitC - digitA + 3) % 3;

        b += digitB * place;
        a /= 3;
        c /= 3;
        place *= 3;
    }

    cout << b << '\n';
    return 0;
}

